<script setup lang="ts">
import { ensureStrings, lazyStrings } from '@/strings';
import { watch, nextTick, ref } from 'vue';
import { TerminalIcon, XIcon } from 'lucide-vue-next';
import WeshTerminalPane from '@/features/wesh-terminal/components/WeshTerminalPane.vue';
import { useDebugWeshTerminalSessions } from '@/composables/useDebugWeshTerminalSessions';
import { useConfirm } from '@/composables/useConfirm';

const props = defineProps<{ isOpen: boolean }>();
const emit = defineEmits<{ (e: 'close'): void }>();

const {
  sessions,
  activeSessionId,
  runCommand,
  completeInput,
  cancelRunningCommand,
  closeSession,
  createWorkerSession,
  reopenSessionIfNeeded,
} = useDebugWeshTerminalSessions();
const { showConfirm } = useConfirm();

const paneRef = ref<InstanceType<typeof WeshTerminalPane> | null>(null);

watch(() => props.isOpen, async (open) => {
  if (!open) return;
  await reopenSessionIfNeeded();
  await nextTick();
  paneRef.value?.focusInput();
}, { immediate: true });

async function handleCloseSession({ sessionId }: { sessionId: string }) {
  const confirmed = await showConfirm({
    title: await ensureStrings.weshTerminal__close_session_question(),
    message: await ensureStrings.weshTerminal__this_will_dispose_the_worker_and_lose_the_session_history_continue(),
    confirmButtonText: await ensureStrings.weshTerminal__close_session(),
    cancelButtonText: await ensureStrings.weshTerminal__cancel(),
    confirmButtonVariant: 'danger',
  });
  if (!confirmed) return;
  await closeSession({ sessionId });
}


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/5863923361eb6415ed332ad80b7dbbfc965095339b997cf6026a30690ce1fa7f.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <Transition name="modal">
    <div
      v-if="isOpen"
      tw-class="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50"
    >
      <div
        tw-class="w-full max-w-4xl h-[85vh] flex flex-col rounded-2xl overflow-hidden border border-gray-700 shadow-2xl bg-gray-950"
      >
        <!-- Header -->
        <div tw-class="flex items-center justify-between gap-3 px-4 py-2.5 border-b border-gray-700/60 shrink-0">
          <div tw-class="flex items-center gap-2">
            <TerminalIcon tw-class="w-4 h-4 text-blue-500 shrink-0" />
            <span tw-class="font-mono text-sm font-bold text-gray-200">{{ lazyStrings.weshTerminal__debug_terminal() }}</span>
          </div>
          <button
            tw-class="p-1 rounded-lg hover:bg-gray-800 transition-colors text-gray-500 hover:text-gray-300"
            :aria-label="lazyStrings.weshTerminal__close_terminal()"
            @click="emit('close')"
          >
            <XIcon tw-class="w-4 h-4" />
          </button>
        </div>

        <!-- Terminal pane fills remaining space -->
        <WeshTerminalPane
          ref="paneRef"
          tw-class="flex-1 min-h-0 flex flex-col"
          :sessions="sessions"
          :active-session-id="activeSessionId"
          :complete-input="completeInput"
          @update:active-session-id="(id) => (activeSessionId = id)"
          @run="({ script }) => runCommand({ script })"
          @create-session="createWorkerSession()"
          @close-session="handleCloseSession"
          @cancel="({ sessionId }) => cancelRunningCommand({ sessionId })"
        />
      </div>
    </div>
  </Transition>
</template>

<style scoped>
.modal-enter-active,
.modal-leave-active {
  transition: opacity 0.2s ease;
}
.modal-enter-from,
.modal-leave-to {
  opacity: 0;
}
</style>
